const $=s=>document.querySelector(s);
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sample={title:'牛顿第二定律：力与运动的关系',summary:'物体的加速度由合外力和质量共同决定。本节课从控制变量出发，建立 F合 = ma，重点理解合外力与加速度的方向关系，以及如何用受力分析解决运动问题。',points:[{title:'加速度取决于合外力与质量',body:'质量一定时，加速度与合外力成正比；合外力一定时，加速度与质量成反比。这里的力，是物体受到的所有外力的合力。',segment:0},{title:'方向相同的是合外力与加速度',body:'加速度的方向始终与合外力一致，但不一定与速度方向相同。物体向前运动时，合外力向后，它会减速。',segment:1},{title:'先受力分析，再列运动方程',body:'明确研究对象，画出受力图，选取正方向，求合外力，再代入 F合 = ma。水平面上也要考虑是否有摩擦力。',segment:2},{title:'用单位检查计算是否合理',body:'质量使用 kg，加速度使用 m/s²，力的单位是 N。2 kg 的物体受到 6 N 的水平合外力，加速度为 3 m/s²。',segment:3}],mistakes:['F合 = ma 中的 F 是合外力，不能直接拿某一个拉力代入。','物体正在运动，不代表合外力一定不为零；合外力为零时也可能做匀速直线运动。'],quiz:[{question:'质量不变，合外力变为原来的 2 倍，加速度如何变化？',answer:'加速度变为原来的 2 倍。由 a = F合 / m 可知，质量不变时二者成正比。',segment:0},{question:'物体向右运动，合外力向左，此时加速度方向是什么？',answer:'向左。加速度与合外力同向，此时物体的速度可能仍向右，但正在减小。',segment:1},{question:'一个 2 kg 的物体受到 10 N 向右的拉力和 4 N 向左的摩擦力，加速度是多少？',answer:'取向右为正，合外力为 10 − 4 = 6 N，因此 a = 6 / 2 = 3 m/s²，方向向右。',segment:3}],segments:[{start:0,text:'今天我们学习牛顿第二定律。质量一定时，加速度与合外力成正比；合外力一定时，加速度与质量成反比。所以，合外力等于质量乘以加速度。'},{start:48,text:'要注意，加速度的方向与合外力的方向一致，不是一定与速度相同。例如物体向右运动，力向左，它会减速。合外力为零时，物体也可以匀速直线运动。'},{start:92,text:'做题时，第一步选研究对象，第二步画受力图，然后规定正方向、求合外力，最后代入牛顿第二定律。不要漏掉摩擦力。'},{start:140,text:'举个例子，一个两千克的物体，受到向右十牛的拉力和向左四牛的摩擦力，合外力是六牛，加速度是三米每二次方秒，方向向右。质量用千克，力用牛顿。'}]};
let report=sample,tab='notes',file=null,audioUrl=null,isSample=true,ready=false,busy=false;
const time=s=>`${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`;
function notice(text){$('#notice').textContent=text;$('#notice').hidden=!text;}
function cite(i){return Number.isInteger(i)&&report?.segments[i]?`<button class="cite" data-cite="${i}">${isSample?'原文片段 '+(i+1):'◷ '+time(report.segments[i].start)} ↗</button>`:'';}
function render(){document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===tab)));$('#export').disabled=!report;$('#quiz-count').textContent=report?.quiz.length||0;
if(!report){$('#content').innerHTML=`<div class="empty"><h3>${busy?'正在整理这堂课…':'录音已就位'}</h3><p>${busy?'正在转写录音并生成学习报告，请保留当前页面。':'可先播放录音，接通 AI 服务后即可生成专属学习笔记。'}</p></div>`;return;}
if(tab==='notes')$('#content').innerHTML=`<div class="summary"><h3 class="section-heading">✦ 本课概览</h3><p>${escapeHtml(report.summary)}</p></div><h3 class="section-heading">核心知识点 <span>${report.points.length} 个知识点</span></h3>${report.points.map((p,i)=>`<section class="point"><span class="number">${String(i+1).padStart(2,'0')}</span><h4>${escapeHtml(p.title)}</h4><p>${escapeHtml(p.body)}</p>${isSample&&i===0?'<div class="formula">F<sub>合</sub> = ma</div>':''}${cite(p.segment)}</section>`).join('')}${report.mistakes.length?`<div class="mistake"><h3>△ 易错提醒</h3>${report.mistakes.map(x=>`<p>• ${escapeHtml(x)}</p>`).join('')}</div>`:''}`;
if(tab==='transcript')$('#content').innerHTML=`<h3 class="section-heading">课堂原文 <span>${isSample?'预置示例文本':'自动转写 · 请核对'}</span></h3>${report.segments.map((s,i)=>`<section class="transcript-row" id="segment-${i}"><button class="cite" data-play="${i}">${isSample?'片段 '+(i+1):'▶ '+time(s.start)}</button><p>${escapeHtml(s.text)}</p></section>`).join('')}`;
if(tab==='quiz')$('#content').innerHTML=`<h3 class="section-heading">课后自测 <span>先想一想，再看答案</span></h3>${report.quiz.map((q,i)=>`<section class="quiz-card"><h3>${i+1}. ${escapeHtml(q.question)}</h3><details><summary>查看参考答案</summary><p>${escapeHtml(q.answer)}</p>${cite(q.segment)}</details></section>`).join('')}`;
}
function selectTab(t){if(!['notes','transcript','quiz'].includes(t))throw Error('未知页面');tab=t;render();}
function loadDemo(){if(busy)return;if(audioUrl)URL.revokeObjectURL(audioUrl);audioUrl=null;file=null;isSample=true;report=sample;$('#audio').pause();$('#audio').removeAttribute('src');$('#audio').load();$('#audio').hidden=true;$('#real-actions').hidden=true;$('#audio-title').textContent='示例课堂文本';$('#audio-hint').textContent='此示例不含音频。导入自己的录音后可播放。';$('#course-title').textContent=sample.title;$('#source-tag').textContent='示例内容 · 非真实录音分析';$('#subject').textContent='高中物理';$('#metadata').textContent='预置课堂文本 · 4 个知识片段 · 约 5 分钟复习';notice('');selectTab('notes');}
function importFile(f){if(busy)return;if(!f)return;if(!/\.(mp3|wav|m4a|webm|ogg|flac)$/i.test(f.name))return notice('请选择 MP3、WAV、M4A、WEBM、OGG 或 FLAC 音频文件。');if(!f.size||f.size>24*1024*1024)return notice('请选择大于 0、且不超过 24 MB 的音频。较长录音请先分段或压缩。');if(audioUrl)URL.revokeObjectURL(audioUrl);file=f;report=null;isSample=false;audioUrl=URL.createObjectURL(f);$('#audio').src=audioUrl;$('#audio').hidden=false;$('#audio-title').textContent=f.name;$('#audio-hint').textContent='音频仅在本页暂存，尚未发送给 AI 服务。';$('#real-actions').hidden=false;$('#course-title').textContent=f.name;$('#subject').textContent='我的课堂';$('#source-tag').textContent='已导入 · 待分析';$('#metadata').textContent=`${(f.size/1024/1024).toFixed(2)} MB · 本页临时文件`;$('#course-name').value='';$('#analyze').disabled=!ready;notice(ready?'':'录音已导入，可以播放。当前尚未接通 AI 服务，请先体验示例课堂；真实分析需配置服务端。');selectTab('notes');}
function exportReport(){if(!report)return;const r=report;const text=`# ${r.title}\n\n${isSample?'【演示数据：预置文本，非真实录音分析】':'【AI 辅助学习报告：请结合录音和教材核对】'}\n\n## 本课概览\n${r.summary}\n\n## 核心知识点\n${r.points.map((p,i)=>`${i+1}. ${p.title}\n${p.body}\n出处：片段 ${p.segment+1}`).join('\n\n')}\n\n## 易错提醒\n${r.mistakes.map(p=>'- '+p).join('\n')}\n\n## 自测练习（含答案）\n${r.quiz.map((q,i)=>`${i+1}. ${q.question}\n参考答案：${q.answer}`).join('\n\n')}\n\n## 课堂原文\n${r.segments.map((s,i)=>`片段 ${i+1}${isSample?'':' ['+time(s.start)+']'}\n${s.text}`).join('\n\n')}`;const u=URL.createObjectURL(new Blob(['\ufeff',text],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='听课本-'+r.title.replace(/[\\/:*?"<>|]/g,'')+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>selectTab(b.dataset.tab));$('#start-quiz').onclick=()=>{selectTab('quiz');$('#content').focus();};$('#demo').onclick=loadDemo;$('#home').onclick=loadDemo;$('#export').onclick=exportReport;['#choose','#new-upload'].forEach(s=>$(s).onclick=()=>$('#file').click());$('#file').onchange=e=>{importFile(e.target.files[0]);e.target.value='';};$('#help').onclick=()=>$('#help-dialog').showModal();$('#close-help').onclick=()=>$('#help-dialog').close();$('#drop').ondragover=e=>{e.preventDefault();$('#drop').classList.add('drag');};$('#drop').ondragleave=()=>$('#drop').classList.remove('drag');$('#drop').ondrop=e=>{e.preventDefault();$('#drop').classList.remove('drag');importFile(e.dataTransfer.files[0]);};$('#audio').onerror=()=>notice('浏览器无法播放这个音频编码。可尝试转换为 MP3 后重新导入。');
$('#content').onclick=e=>{const b=e.target.closest('[data-cite],[data-play]');if(!b||!report)return;const i=Number(b.dataset.cite??b.dataset.play);if(b.dataset.cite!==undefined){selectTab('transcript');const el=$('#segment-'+i);el?.classList.add('highlight');el?.scrollIntoView({behavior:'smooth',block:'center'});}if(!isSample&&audioUrl){$('#audio').currentTime=report.segments[i].start;$('#audio').play().catch(()=>notice('请点击播放器的播放按钮继续。'));}};
$('#analyze').onclick=async()=>{if(!file||!ready||busy)return;busy=true;$('#analyze').disabled=true;$('#demo').disabled=true;notice('正在转写和分析，请勿关闭页面。');render();try{const response=await fetch('/api/analyze',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-Filename':encodeURIComponent(file.name),'X-Course':encodeURIComponent($('#course-name').value),'X-Focus':encodeURIComponent($('#focus').value)},body:file,signal:AbortSignal.timeout(240000)});const result=await response.json();if(!response.ok)throw Error(result.error||'分析未完成，请重试。');report=result;$('#course-title').textContent=result.title;$('#source-tag').textContent='AI 学习笔记 · 请核对';$('#metadata').textContent=`${result.segments.length} 个原文片段 · ${result.points.length} 个知识点`;$('#audio-hint').textContent='点击笔记中的时间，可以回听对应原文。';notice('学习报告已生成。建议核对公式、数字和关键结论。');}catch(e){notice(e.name==='TimeoutError'?'分析超时，请缩短录音后重试。':e.message);}finally{busy=false;$('#analyze').disabled=!ready;$('#demo').disabled=false;render();}};
$('.wave').innerHTML=Array.from({length:40},(_,i)=>`<i style="height:${12+Math.abs(Math.sin(i*1.6)*Math.cos(i*.4))*34}px"></i>`).join('');render();
fetch('/api/status').then(r=>r.ok?r.json():null).then(s=>{ready=!!s?.configured;$('#service-status').textContent=ready?'AI 服务已配置':'演示模式';$('#analyze').disabled=!ready;}).catch(()=>{});
if(document.modelContext?.registerTool){const lifetime=new AbortController();window.addEventListener('pagehide',()=>lifetime.abort(),{once:true});for(const tool of [{name:'open_sample_lesson',title:'打开示例课堂',description:'切换到明确标注的预置学生课堂示例，会清除当前临时导入。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(input&&Object.keys(input).length)throw Error('无需参数');if(busy)throw Error('正在分析');loadDemo();return{title:report.title,isSample};}},{name:'navigate_study_tab',title:'切换学习视图',description:'切换笔记、原文或自测。',inputSchema:{type:'object',properties:{tab:{type:'string',enum:['notes','transcript','quiz']}},required:['tab'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='tab'))throw Error('参数错误');selectTab(input.tab);return{tab,isSample};}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifetime.signal})).catch(()=>{});}catch{}}}

